using System.Buffers.Binary;using System.Net;using System.Net.Sockets;using System.Text;
using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(5));var token=timeout.Token;var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();
try{using var client=new TcpClient();await client.ConnectAsync(IPAddress.Loopback,((IPEndPoint)listener.LocalEndpoint).Port,token);using var server=await listener.AcceptTcpClientAsync(token);
using var combined=new MemoryStream();await Write(combined,"Chào",token);await Write(combined,"An",token);await client.GetStream().WriteAsync(combined.ToArray(),token);
Console.WriteLine(await Read(server.GetStream(),token));Console.WriteLine(await Read(server.GetStream(),token));
using var tooLarge=new MemoryStream(new byte[]{0,0,1,0});try{await Read(tooLarge,token);}catch(InvalidDataException){Console.WriteLine("oversize");}
using var shortBody=new MemoryStream(new byte[]{0,0,0,2,65});try{await Read(shortBody,token);}catch(EndOfStreamException){Console.WriteLine("EOF payload");}
using var cancel=new CancellationTokenSource();var waiting=Read(server.GetStream(),cancel.Token);cancel.Cancel();try{await waiting;}catch(OperationCanceledException){Console.WriteLine("canceled");}
}finally{listener.Stop();}
static async Task Write(Stream stream,string text,CancellationToken t){byte[] body=Encoding.UTF8.GetBytes(text);byte[] h=new byte[4];BinaryPrimitives.WriteInt32BigEndian(h,body.Length);await stream.WriteAsync(h,t);await stream.WriteAsync(body,t);}
static async Task<string> Read(Stream stream,CancellationToken t){byte[] h=new byte[4];await stream.ReadExactlyAsync(h,t);int n=BinaryPrimitives.ReadInt32BigEndian(h);if(n<0||n>128)throw new InvalidDataException();byte[] body=new byte[n];await stream.ReadExactlyAsync(body,t);return Encoding.UTF8.GetString(body);}

